// 🟢 Coleta todas as carteiras que vieram nos itens de entrada
let carteiras = $items()
  .map(item => item.json.carteira)   // pega o valor de cada item
  .filter(c => c && c.trim() !== ""); // remove nulos e vazios

// 🧩 Se não encontrar nada válido, garante retorno vazio
if (carteiras.length === 0) {
  carteiras = [""];
}

// 🧾 Retorna uma saída (item) para cada carteira encontrada
return carteiras.map(nome => ({
  json: {
    carteira: nome.trim()
  }
}));

// 🟢 Pega o valor original
let carteiraRaw = $json.carteira || "";
let idSessao = $json.idsessao || null;

// 🧩 Cria um array para armazenar as carteiras encontradas
let carteiras = [];

try {
  // 🔍 Tenta converter se for string JSON (ex: "[\"Jaque\",\"Taynara\"]")
  const parsed = JSON.parse(carteiraRaw);

  // ✅ Se for um array válido e tiver itens, adiciona todos
  if (Array.isArray(parsed) && parsed.length > 0) {
    carteiras = parsed.map(c => (c || "").trim());
  }
} catch (e) {
  // ⚙️ Se não for JSON válido, limpa e tenta separar por vírgulas
  carteiras = carteiraRaw
    .replace(/[\[\]\\"]/g, "") // remove colchetes e aspas
    .split(",") // divide por vírgula
    .map(c => c.trim()) // remove espaços extras
    .filter(c => c !== ""); // remove vazios
}

// 🧾 Caso não encontre nenhuma carteira válida
if (carteiras.length === 0) {
  carteiras = [""]; // evita erro de retorno vazio
}

// 🔁 Retorna uma saída para cada carteira (mantendo o idsessao)
return carteiras.map(nome => ({
  json: {
    carteira: nome,
    idsessao: idSessao
  }
}));

// 🔤 Normaliza texto (remove acentos e caixa)
const normalize = s => (s || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim();

// 📋 Dados das carteiras (entrada principal)
const carteiras = $items("carteira").map(i => ({
  nome: normalize(i.json.carteira),
  carteiraOriginal: i.json.carteira,
  idsessao: i.json.idsessao
}));

// 👥 Dados dos usuários (node de origem)
const usuarios = $items("Edit Fields7").map(i => ({
  nome: normalize(i.json.Nome),
  nomeOriginal: i.json.Nome,
  idusuario: i.json.idusuario,
  equipe: i.json.equipe,
  idsessao: i.json.idsessao
}));

// 🔎 Faz o cruzamento por nome e idsessao
const encontrados = carteiras.map(c => {
  const match = usuarios.find(u => u.nome === c.nome && u.idsessao === c.idsessao);
  if (!match) return null;
  return {
    json: {
      carteira: c.carteiraOriginal,
      nome: match.nomeOriginal,
      idusuario: match.idusuario,
      idsessao: match.idsessao,
      equipe: match.equipe,
      status: "Encontrado ✅"
    }
  };
}).filter(Boolean); // remove nulos

// 🚀 Retorna apenas os encontrados
return encontrados;

